solution:
def find_user(users, name):
    if name not in users:
        raise KeyError(name)
    return users[name]


def greet(users, name):
    try:
        value = find_user(users, name)
    except KeyError:
        return "등록되지 않은 사용자예요"
    return f"안녕하세요, {value}님"

setup:
def raises(fn):
    try:
        fn()
    except Exception as e:
        return type(e).__name__
    return None


def err_msg(fn):
    try:
        fn()
    except Exception as e:
        return str(e)
    return None
